export const HAND_CASES={
 doors:{title:'Retirar una obstrucción de puerta',group:'doors',symptom:'La hoja no completa el cierre: hay un objeto en la guía.',steps:[['Preparar','Acciona el interruptor para dejar sin energía el mecanismo virtual.'],['Retirar','Con Mano, toma la bolsa atrapada y llévala a la bandeja. También puedes tocar el objeto y después la bandeja.'],['Comprobar','Habilita la energía de ensayo. Mueve el mando de puerta hasta abrir completamente y después ciérrala.']],cause:'Obstáculo en el recorrido de la hoja.'},
 ventilation:{title:'Reconectar la ventilación',group:'roof',symptom:'La orden de ventilación llega, pero el conector del ejercicio está suelto.',steps:[['Preparar','Desconecta la alimentación del ejercicio.'],['Abrir','Selecciona Destornillador y afloja los cuatro tornillos. Con Mano, lleva la tapa a la bandeja.'],['Reconectar','Con Mano, lleva el conector suelto al puerto marcado.'],['Cerrar','Lleva la tapa de la bandeja a su marco. Con Destornillador, aprieta los cuatro tornillos.'],['Comprobar','Habilita la alimentación. Pulsa Probar ventilación y observa el giro representado.']],cause:'Conector auxiliar desconectado en el escenario.'},
 running:{title:'Intervención de rodadura en el tren',group:'mechanics',symptom:'La marca naranja representa una anomalía en la rodadura.',steps:[['Preparar','Desconecta la alimentación y bloquea el apoyo virtual.'],['Retirar','Primero toca la banda para registrar el corte visible. Con Llave, libera las ocho fijaciones. Después, con Mano, toma la rueda señalada y llévala a la bandeja.'],['Sustituir','Toma el repuesto de rueda de la bandeja de herramientas y colócalo en el eje.'],['Fijar','Con Llave, actúa sobre las ocho fijaciones de la rueda. No se asigna un par de apriete real.'],['Comprobar','Mantén el equipo sin energía. Usa el mando de giro para representar una vuelta completa.']],cause:'Anomalía de rodadura representada con una marca virtual.'},
 electrical:{title:'Reparar un circuito de iluminación',group:'interior',symptom:'La fuente virtual entrega 24 V CC, pero la lámpara H1 no enciende.',steps:[['Aislar y verificar','Apaga S1. Selecciona Multímetro en V CC y coloca sus dos puntas en TP+ y TP−: debe marcar 0 V.'],['Abrir tablero','Con Destornillador, afloja los tornillos A, B, C y D. Con Mano, lleva la tapa a la bandeja.'],['Diagnosticar F1','Selecciona Multímetro en continuidad y coloca sus puntas en los dos extremos de F1. OL confirma el fusible abierto del ejercicio.'],['Sustituir F1','Retira las dos puntas de F1. Con Mano, lleva F1 a la bandeja. Toma el repuesto compatible y colócalo en el portafusible.'],['Cerrar tablero','Con las puntas retiradas, recoloca la tapa y aprieta los cuatro tornillos con Destornillador.'],['Comprobar H1','Enciende S1. Selecciona V CC y mide entre H+ y H−: comprueba 24 V y la lámpara encendida.'],['Recoger el multímetro','Retira las dos puntas de H+ y H− y devuélvelas a los soportes del instrumento. Después termina la misión.']],cause:'Fusible F1 abierto en un circuito didáctico de 24 V CC.'}
};
const pair=(a,b,x,y)=>(a===x&&b===y)||(a===y&&b===x);
export class HandsMaintenance{
 constructor(id='doors'){this.reset(id);}
 reset(id){if(!HAND_CASES[id])throw Error('Actividad no disponible.');Object.assign(this,{id,tool:'hand',power:true,isolated:false,zeroVerified:false,screws:Array.from({length:4},()=>true),coverOpen:false,coverEverOpened:false,obstacle:true,plugConnected:false,standLocked:false,wheelInspected148:false,wheelRemoved:false,wheelReplaced:false,wheelBolts:Array.from({length:8},()=>id==='running'),fuseRemoved:false,fuseReplaced:false,continuityConfirmed:false,lampVerified:false,doorPosition:id==='doors'?12:0,doorOpened:false,doorClosed:false,fanPassed:false,rotation:0,selectedItem:null,meterMode:'V',probeColour:'red',probes:{red:null,black:null},verifiedReadings:[],log:[],message:'Observa el síntoma y sigue el primer paso del manual.'});}
 get stage(){if(this.id==='doors')return !this.isolated?0:this.obstacle?1:!this.doorClosed?2:3;if(this.id==='ventilation')return !this.isolated?0:!this.coverEverOpened?1:!this.plugConnected?2:this.coverOpen||!this.screws.every(Boolean)?3:!this.fanPassed?4:5;if(this.id==='running')return !this.isolated||!this.standLocked?0:!this.wheelRemoved?1:!this.wheelReplaced?2:!this.wheelBolts.every(Boolean)?3:this.rotation<360?4:5;return !this.zeroVerified?0:!this.coverEverOpened?1:!this.continuityConfirmed?2:!this.fuseReplaced?3:this.coverOpen||!this.screws.every(Boolean)?4:!this.lampVerified?5:Object.values(this.probes).some(Boolean)?6:7;}
 get complete(){return this.stage===HAND_CASES[this.id].steps.length;}
 get repaired(){return this.id==='doors'?!this.obstacle:this.id==='ventilation'?this.plugConnected:this.id==='running'?this.wheelReplaced:this.fuseReplaced;}
 say(text){this.message=text;this.log.push(text);return text;}
 require(condition,message){if(!condition)throw Error(message);}
 safe(){this.require(!this.power,'Desconecta la alimentación virtual antes de intervenir.');if(this.id==='electrical')this.require(this.zeroVerified,'Verifica 0 V entre TP+ y TP− antes de abrir o intervenir el tablero.');}
 use(tool){this.tool=tool;this.selectedItem=null;return this.say({hand:'Mano: toma una pieza y elige su destino.',screwdriver:'Destornillador: actúa sobre los cuatro tornillos A–D.',wrench:'Llave: actúa sobre las fijaciones de la rueda.',meter:'Multímetro: elige V CC o continuidad y coloca ambas puntas.'}[tool]);}
 reading(){const {red:a,black:b}=this.probes;if(!a||!b)return {value:'—',label:'Coloca las dos puntas'};if(this.meterMode==='Ω'){if(this.power)return {value:'BLOQUEADO',label:'Desconecta S1 antes de medir continuidad'};if(pair(a,b,'fuseA','fuseB'))return {value:this.fuseReplaced?'0.2 Ω':'OL',label:this.fuseReplaced?'Continuidad virtual':'Circuito abierto'};return {value:'—',label:'Mide los dos extremos de F1'};}const v=this.power?24:0,out=this.fuseReplaced&&!this.fuseRemoved?v:0;const potentials={sourcePlus:v,return:0,fuseA:v,fuseB:out,lampPlus:out,lampMinus:0};if(!(a in potentials&&b in potentials))return {value:'—',label:'Puntos no disponibles'};return {value:(potentials[a]-potentials[b]).toFixed(1)+' V',label:'Tensión continua simulada'};}
 measure(){const a=this.probes.red,b=this.probes.black;if(this.id!=='electrical')return;if(this.meterMode==='V'&&!this.power&&pair(a,b,'sourcePlus','return')){if(!this.zeroVerified)this.verifiedReadings.push({step:'TP+ / TP−',value:this.reading().value});this.zeroVerified=true;this.say('0 V verificados en TP+ / TP−. Puedes abrir el tablero del ejercicio.');}if(this.meterMode==='Ω'&&!this.power&&this.zeroVerified&&this.coverOpen&&pair(a,b,'fuseA','fuseB')&&!this.fuseReplaced){if(!this.continuityConfirmed)this.verifiedReadings.push({step:'F1',value:this.reading().value});this.continuityConfirmed=true;this.say('F1 mide OL: fusible abierto. Ya puedes retirar y sustituir F1.');}if(this.meterMode==='V'&&this.power&&this.fuseReplaced&&!this.fuseRemoved&&!this.coverOpen&&this.screws.every(Boolean)&&pair(a,b,'lampPlus','lampMinus')){if(!this.lampVerified)this.verifiedReadings.push({step:'H+ / H−',value:this.reading().value});this.lampVerified=true;this.say('H1 encendida y 24 V comprobados. Retira ahora ambas puntas para terminar la intervención.');}}
 removeProbe(colour=null){this.require(this.id==='electrical','Las puntas pertenecen al ejercicio eléctrico.');if(colour!==null)this.require(colour==='red'||colour==='black','Punta no disponible.');const colours=colour?[colour]:['red','black'];for(const c of colours)this.probes[c]=null;this.probeColour=Object.values(this.probes).some(Boolean)?colour||'red':'red';this.selectedItem=null;this.toolMotion=null;this.tool='hand';return this.say(Object.values(this.probes).some(Boolean)?'Punta retirada. Recoge la otra punta o continúa con la medición.':this.lampVerified?'Ambas puntas recogidas. Reparación y comprobación final terminadas.':'Puntas recogidas. Ya puedes continuar con el banco.');}
 probe(target){this.require(this.tool==='meter','Selecciona Multímetro para colocar las puntas.');this.require(['sourcePlus','return','fuseA','fuseB','lampPlus','lampMinus'].includes(target),'Selecciona un punto de medida.');if(target.startsWith('fuse'))this.require(this.coverOpen,'Abre la tapa para acceder a F1.');this.probes[this.probeColour]=target;this.probeColour=this.probeColour==='red'?'black':'red';this.say('Punta conectada. '+this.reading().label);this.measure();}
 act(target){try{return this.perform(target);}catch(e){this.message=e.message;return this.message;}}
 perform(target){if(target==='power'){if(this.power){this.power=false;this.isolated=true;this.say('S1 abierto: alimentación virtual desconectada.');this.measure();}else{this.require(!this.coverOpen&&this.screws.every(Boolean),'Recoloca la tapa y fija los cuatro tornillos antes de energizar.');if(this.id==='doors')this.require(!this.obstacle,'Retira el obstáculo antes del ensayo.');if(this.id==='ventilation')this.require(this.plugConnected,'Reconecta el equipo antes del ensayo.');if(this.id==='electrical')this.require(this.fuseReplaced,'Sustituye F1 antes del ensayo final.');this.power=true;this.say('Alimentación de ensayo habilitada.');this.measure();}return;}
 if(target==='stand'){this.safe();this.standLocked=true;return this.say('Apoyo virtual bloqueado. Puedes retirar la rueda.');}
 if(target.startsWith('screw')){this.safe();this.require(this.tool==='screwdriver','Selecciona Destornillador para los tornillos.');this.require(!this.coverOpen,'Recoloca la tapa antes de fijarla.');const i=Number(target.slice(-1))-1;this.require(Number.isInteger(i)&&i>=0&&i<this.screws.length,'Tornillo no disponible.');if(!this.coverEverOpened){this.screws[i]=false;this.say('Tornillo '+String.fromCharCode(65+i)+' aflojado.');}else{this.screws[i]=true;this.say('Tornillo '+String.fromCharCode(65+i)+' fijado en el ejercicio.');}return;}
 if(target.startsWith('bolt')){this.safe();this.require(this.tool==='wrench','Selecciona Llave para las fijaciones.');this.require(this.id==='running'&&this.standLocked,'Bloquea primero el apoyo del equipo instalado.');const i=Number(target.slice(4))-1;this.require(Number.isInteger(i)&&i>=0&&i<this.wheelBolts.length,'Fijación no disponible.');this.wheelBolts[i]=this.wheelReplaced;return this.say('Fijación '+(i+1)+(this.wheelReplaced?' colocada y asegurada en el tren.':' retirada y depositada en la bandeja.'));}
 if(target==='testFan'){this.require(this.power&&this.plugConnected&&!this.coverOpen&&this.screws.every(Boolean),'Reconecta, cierra la tapa y habilita la alimentación antes de probar.');this.verifiedReadings.push({step:'Ensayo funcional de ventilación',value:'Conector firme, giro estable y tapa fijada'});this.fanPassed=true;return this.say('Ventilador respondiendo en el esquema. Práctica completada.');}
 if(['sourcePlus','return','fuseA','fuseB','lampPlus','lampMinus'].includes(target))return this.probe(target);
 if(['cover','obstacle','wheel','fuse','newFuse','newWheel','plug'].includes(target)){this.require(this.tool==='hand','Selecciona Mano para tomar y colocar piezas.');this.safe();if(target==='cover'&&!this.coverOpen)this.require(!this.screws.some(Boolean),'Afloja los cuatro tornillos antes de levantar la tapa.');if(target==='wheel'&&!this.wheelInspected148){this.wheelInspected148=true;return this.say('Corte de la banda registrado. Requiere cambio de rueda en este banco; no representa una intervención en un tren en servicio.');}if(target==='wheel'){this.require(this.standLocked,'Bloquea el apoyo virtual antes de retirar la rueda.');this.require(!this.wheelRemoved,'La rueda anterior ya está en la bandeja.');this.require(!this.wheelBolts.some(Boolean),'Retira las ocho fijaciones antes de levantar la rueda.');}if(target==='fuse'){this.require(this.coverOpen,'Abre la tapa para acceder al fusible.');this.require(this.continuityConfirmed,'Mide continuidad en F1 para identificar la avería antes de retirarlo.');this.require(!this.fuseRemoved,'F1 ya está retirado.');}if(target==='obstacle')this.require(this.obstacle,'El obstáculo ya está retirado.');if(target==='plug')this.require(this.coverOpen,'Abre la tapa antes de reconectar.');this.selectedItem=target;return this.say('Pieza tomada. Llévala a '+(target==='newFuse'?'F1':target==='newWheel'?'el eje':target==='plug'?'el puerto':target==='cover'&&this.coverOpen?'el marco de la tapa':'la bandeja')+'.');}
 if(['tray','coverSeat','fuseSocket','wheelHub','port'].includes(target)){this.require(this.tool==='hand','Selecciona Mano para colocar la pieza.');this.safe();const item=this.selectedItem;this.require(item,'Toma primero una pieza con Mano.');if(target==='tray'){if(item==='cover'){this.coverOpen=true;this.coverEverOpened=true;}else if(item==='obstacle')this.obstacle=false;else if(item==='wheel')this.wheelRemoved=true;else if(item==='fuse')this.fuseRemoved=true;else throw Error('Ese elemento no corresponde a la bandeja de piezas retiradas.');}else if(target==='coverSeat'){this.require(item==='cover','Coloca la tapa en su marco.');this.require(this.repaired,'Completa la intervención antes de cerrar la tapa.');if(this.id==='electrical')this.require(!Object.values(this.probes).some(p=>p==='fuseA'||p==='fuseB'),'Retira las puntas de F1 con Quitar puntas antes de cerrar la tapa.');this.coverOpen=false;this.screws=this.screws.map(()=>false);}else if(target==='fuseSocket'){this.require(item==='newFuse'&&this.fuseRemoved,'Retira F1 y toma el repuesto compatible antes de colocarlo.');this.fuseReplaced=true;this.fuseRemoved=false;}else if(target==='wheelHub'){this.require(item==='newWheel'&&this.wheelRemoved,'Retira la rueda anterior y toma el repuesto.');this.wheelReplaced=true;}else{this.require(item==='plug','Lleva el conector al puerto correspondiente.');this.plugConnected=true;}this.selectedItem=null;return this.say('Pieza colocada. Consulta el siguiente paso del manual.');}
 throw Error('Selecciona una pieza o una herramienta del equipo instalado.');}
 door(value){try{this.require(this.id==='doors'&&this.power,'Habilita la energía de ensayo para accionar la puerta.');this.require(!this.obstacle,'El obstáculo impide el recorrido de la puerta.');this.doorPosition=Math.max(0,Math.min(100,Number(value)));if(this.doorPosition>=99.99)this.doorOpened=true;if(this.doorOpened&&this.doorPosition<=.01){this.verifiedReadings.push({step:'Ciclo completo',value:'Guía libre · apertura y confirmación de cierre'});this.doorClosed=true;this.say('Apertura y cierre comprobados. Práctica completada.');}}catch(e){this.message=e.message;}}
 rotate(value){try{this.safe();this.require(this.wheelReplaced&&this.wheelBolts.every(Boolean),'Coloca y fija la rueda antes del ensayo de giro.');this.rotation=Math.max(0,Math.min(360,Number(value)));if(this.rotation>=360)this.say('Una vuelta representada sin la incidencia virtual. Práctica completada.');}catch(e){this.message=e.message;}}
}
